--
-- Table structure for table `Reserva`
--

DROP TABLE IF EXISTS `Reserva`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Reserva` (
  `folio` varchar(20) NOT NULL,
  `estatus` tinyint DEFAULT NULL,
  `fecha` date DEFAULT NULL,
  `subtotal` decimal(10,2) DEFAULT NULL,
  `iva` decimal(10,2) DEFAULT NULL,
  `total` decimal(10,2) DEFAULT NULL,
  `fecha_cancelacion_reserva` datetime DEFAULT NULL,
  `correo` varchar(100) DEFAULT NULL,
  `id_cuenta` int DEFAULT NULL,
  `id_sucursal` int NOT NULL,
  PRIMARY KEY (`folio`),
  KEY `correo` (`correo`),
  KEY `id_cuenta` (`id_cuenta`),
  KEY `fk_reserva_sucursal` (`id_sucursal`),
  CONSTRAINT `fk_reserva_sucursal` FOREIGN KEY (`id_sucursal`) REFERENCES `Sucursal` (`id_sucursal`),
  CONSTRAINT `reserva_ibfk_1` FOREIGN KEY (`correo`) REFERENCES `Usuario` (`correo`),
  CONSTRAINT `reserva_ibfk_2` FOREIGN KEY (`id_cuenta`) REFERENCES `Cuenta` (`id_cuenta`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

